    public static function svg(string $name, string $class = '', int $size = 20): string
    {
        $paths = self::PATHS[$name] ?? self::PATHS['info'];
        $classAttr = trim('icon ' . $class);
        // aria-hidden: icons are decorative; the visible text (or an aria-label on the button) carries the meaning.
        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">%s</svg>',
            htmlspecialchars($classAttr, ENT_QUOTES),
            $size,
            $size,
            $paths
        );
    }

    /**
     * @return list<string>
     */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
